pub fn getNameFromSpec(spec: []const u8) []const u8 {
            const unquoted = (if (((spec[0] == 34) and (spec[@as(usize, @intCast((spec.len - 1)))] == 34))) spec[1..(spec.len - 1)] else spec);
            if ((unquoted[0] == 64)) {
                if (strings.indexOf(unquoted[1..], "@")) |second_at| {
                    _ = &second_at;
                    const end_idx = (second_at + 1);
                    return unquoted[0..end_idx];
                }
                return unquoted;
            }
            if (strings.indexOf(unquoted, "@npm:")) |npm_idx| {
                _ = &npm_idx;
                return unquoted[0..npm_idx];
            } else {
                if (strings.indexOf(unquoted, "@https://")) |url_idx| {
                    _ = &url_idx;
                    return unquoted[0..url_idx];
                } else {
                    if (strings.indexOf(unquoted, "@git+")) |git_idx| {
                        _ = &git_idx;
                        return unquoted[0..git_idx];
                    } else {
                        if (strings.indexOf(unquoted, "@github:")) |gh_idx| {
                            _ = &gh_idx;
                            return unquoted[0..gh_idx];
                        } else {
                            if (strings.indexOf(unquoted, "@file:")) |file_idx| {
                                _ = &file_idx;
                                return unquoted[0..file_idx];
                            } else {
                                if (strings.indexOf(unquoted, "@")) |idx| {
                                    _ = &idx;
                                    return unquoted[0..idx];
                                }
                            }
                        }
                    }
                }
            }
            return unquoted;
    }

pub fn getVersionFromSpec(spec: []const u8) ?[]const u8 {
            const unquoted = (if (((spec[0] == 34) and (spec[@as(usize, @intCast((spec.len - 1)))] == 34))) spec[1..(spec.len - 1)] else spec);
            if ((unquoted[0] == 64)) {
                if (strings.indexOfChar(unquoted[1..], 64)) |second_at_pos| {
                    _ = &second_at_pos;
                    const version_start = ((second_at_pos + "@".len) + 1);
                    const version_part = unquoted[version_start..];
                    if ((strings.hasPrefixComptime(version_part, "npm:") and (version_part.len > 4))) {
                        return version_part["npm:".len..];
                    }
                    return version_part;
                }
                return null;
            } else {
                if (strings.indexOf(unquoted, "@npm:")) |npm_idx| {
                    _ = &npm_idx;
                    const after_npm = ((npm_idx + "npm:".len) + 1);
                    if ((after_npm < unquoted.len)) {
                        return unquoted[after_npm..];
                    }
                    return null;
                } else {
                    if (strings.indexOf(unquoted, "@https://")) |url_idx| {
                        _ = &url_idx;
                        const after_at = (url_idx + 1);
                        if ((after_at < unquoted.len)) {
                            return unquoted[after_at..];
                        }
                        return null;
                    } else {
                        if (strings.indexOf(unquoted, "@git+")) |git_idx| {
                            _ = &git_idx;
                            const after_at = (git_idx + 1);
                            if ((after_at < unquoted.len)) {
                                return unquoted[after_at..];
                            }
                            return null;
                        } else {
                            if (strings.indexOf(unquoted, "@github:")) |gh_idx| {
                                _ = &gh_idx;
                                const after_at = (gh_idx + 1);
                                if ((after_at < unquoted.len)) {
                                    return unquoted[after_at..];
                                }
                                return null;
                            } else {
                                if (strings.indexOf(unquoted, "@file:")) |file_idx| {
                                    _ = &file_idx;
                                    const after_at = (file_idx + 1);
                                    if ((after_at < unquoted.len)) {
                                        return unquoted[after_at..];
                                    }
                                    return null;
                                } else {
                                    if (strings.indexOf(unquoted, "@")) |idx| {
                                        _ = &idx;
                                        const after_at = (idx + 1);
                                        if ((after_at < unquoted.len)) {
                                            return unquoted[after_at..];
                                        }
                                        return null;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            return null;
    }

pub fn isGitDependency(version: []const u8) bool {
            return (((strings.hasPrefixComptime(version, "git+") or strings.hasPrefixComptime(version, "git://")) or strings.hasPrefixComptime(version, "github:")) or strings.hasPrefixComptime(version, "https://github.com/"));
    }

pub fn isNpmAlias(version: []const u8) bool {
            return strings.hasPrefixComptime(version, "npm:");
    }

pub fn isRemoteTarball(version: []const u8) bool {
            return (strings.hasPrefixComptime(version, "https://") and strings.endsWithComptime(version, ".tgz"));
    }

pub fn isWorkspaceDependency(version: []const u8) bool {
            return (strings.hasPrefixComptime(version, "workspace:") or strings.eqlComptime(version, "*"));
    }

pub fn isFileDependency(version: []const u8) bool {
            return ((strings.hasPrefixComptime(version, "file:") or strings.hasPrefixComptime(version, "./")) or strings.hasPrefixComptime(version, "../"));
    }

pub fn parseGitUrl(allocator: Allocator, version: []const u8) !YarnGitUrl {
            var url = version;
            _ = &url;
            var commit: ?[]const u8 = null;
            _ = &commit;
            var owner: ?[]const u8 = null;
            _ = &owner;
            var repo: ?[]const u8 = null;
            _ = &repo;
            if (strings.hasPrefixComptime(url, "git+")) {
                url = url[4..];
            }
            if (strings.indexOf(url, "#")) |hash_idx| {
                _ = &hash_idx;
                commit = url[(hash_idx + 1)..];
                url = url[0..hash_idx];
            }
            if (strings.hasPrefixComptime(version, "github:")) {
                const github_path = version["github:".len..];
                var path_without_commit = github_path;
                _ = &path_without_commit;
                if (strings.indexOf(github_path, "#")) |idx| {
                    _ = &idx;
                    path_without_commit = github_path[0..idx];
                }
                if (strings.indexOf(path_without_commit, "/")) |slash_idx| {
                    _ = &slash_idx;
                    owner = path_without_commit[0..slash_idx];
                    repo = path_without_commit[(slash_idx + 1)..];
                }
                url = try std.fmt.allocPrint(allocator, "https://github.com/{s}", .{ path_without_commit });
            } else {
                if (strings.contains(url, "github.com")) {
                    var remaining = url;
                    _ = &remaining;
                    if (strings.indexOf(remaining, "github.com/")) |idx| {
                        _ = &idx;
                        remaining = remaining[(idx + "github.com/".len)..];
                    }
                    if (strings.indexOf(remaining, "/")) |slash_idx| {
                        _ = &slash_idx;
                        owner = remaining[0..slash_idx];
                        const after_owner = remaining[(slash_idx + 1)..];
                        if (strings.endsWithComptime(after_owner, ".git")) {
                            repo = after_owner[0..(after_owner.len - ".git".len)];
                        } else {
                            repo = after_owner;
                        }
                    }
                }
            }
            return YarnGitUrl{ .url = url, .commit = commit, .owner = owner, .repo = repo };
    }

pub fn parseNpmAlias(version: []const u8) YarnNpmAlias {
            if ((version.len <= 4)) {
                return YarnNpmAlias{ .package = "", .version = "*" };
            }
            const npm_part = version[4..];
            if (strings.indexOf(npm_part, "@")) |at_idx| {
                _ = &at_idx;
                const ver = (if (((at_idx + 1) < npm_part.len)) npm_part[(at_idx + 1)..] else "*");
                return YarnNpmAlias{ .package = npm_part[0..at_idx], .version = ver };
            }
            return YarnNpmAlias{ .package = npm_part, .version = "*" };
    }

pub fn getPackageNameFromResolvedUrl(url: []const u8) ?[]const u8 {
            if (strings.indexOf(url, "/-/")) |dash_idx| {
                _ = &dash_idx;
                var slash_count: usize = 0;
                _ = &slash_count;
                var last_slash: usize = 0;
                _ = &last_slash;
                var second_last_slash: usize = 0;
                _ = &second_last_slash;
                var i = dash_idx;
                _ = &i;
                while ((i > 0)) : (i = (i - 1)) {
                    if ((url[@as(usize, @intCast((i - 1)))] == 47)) {
                        slash_count = (slash_count + 1);
                        if ((slash_count == 1)) {
                            last_slash = (i - 1);
                        } else {
                            if ((slash_count == 2)) {
                                second_last_slash = (i - 1);
                                break;
                            }
                        }
                    }
                }
                if (((last_slash < dash_idx) and (url[@as(usize, @intCast((last_slash + 1)))] == 64))) {
                    return url[(second_last_slash + 1)..dash_idx];
                } else {
                    return url[(last_slash + 1)..dash_idx];
                }
            }
            return null;
    }
};

pub const YarnLock = struct {
    entries: std.array_list.Managed(YarnLockEntry),
    allocator: Allocator,

pub fn init(allocator: Allocator) YarnLock {
            return .{ .entries = std.array_list.Managed(YarnLockEntry).init(allocator), .allocator = allocator };
    }

pub fn deinit(self: *YarnLock) void {
            for (self.entries.items) |*entry| {
                _ = &entry;
                _ = (entry.*).deinit(self.allocator);
            }
            _ = self.entries.deinit();
    }

pub fn parse(self: *YarnLock, content: []const u8) !void {
            var lines = strings.split(content, "\n");
            _ = &lines;
            var current_entry: ?YarnLockEntry = null;
            _ = &current_entry;
            var current_specs = StringList.init(self.allocator);
            _ = &current_specs;
            var _guard_current_specs = DeinitGuard(@TypeOf(current_specs)){ .target = (blk: {
            break :blk (&current_specs);

