            var current_deps: ?StringMap = null;
            _ = &current_deps;
            var current_optional_deps: ?StringMap = null;
            _ = &current_optional_deps;
            var current_peer_deps: ?StringMap = null;
            _ = &current_peer_deps;
            var current_dev_deps: ?StringMap = null;
            _ = &current_dev_deps;
            var current_dep_type: ?DependencyType = null;
            _ = &current_dep_type;
            while (lines.next()) |line_| {
                const line = std.mem.trimRight(u8, line_, " \r\t");
                if (((line.len == 0) or (line[0] == 35))) {
                    continue;
                }
                var indent: usize = 0;
                _ = &indent;
                while (((indent < line.len) and (line[@as(usize, @intCast(indent))] == 32))) {
                    indent = (indent + 1);
                }
                const trimmed = strings.trim(line[indent..], " \r\t");
                if ((trimmed.len == 0)) {
                    continue;
                }
                if (((indent == 0) and strings.endsWithComptime(trimmed, ":"))) {
                    if ((current_entry != null)) {
                        current_entry.?.dependencies = current_deps;
                        current_entry.?.optionalDependencies = current_optional_deps;
                        current_entry.?.peerDependencies = current_peer_deps;
                        current_entry.?.devDependencies = current_dev_deps;
                        _ = try self.consolidateAndAppendEntry(current_entry.?);
                    }
                    _ = current_specs.clearRetainingCapacity();
                    const specs_str = trimmed[0..(trimmed.len - 1)];
                    var specs_it = strings.split(specs_str, ",");
                    _ = &specs_it;
