                    if (strings.indexOf(trimmed, " ")) |space_idx| {
                        _ = &space_idx;
                        const key = strings.trim(trimmed[0..space_idx], " \"");
                        const value = strings.trim(trimmed[(space_idx + 1)..], " \"");
                        if (strings.eqlComptime(key, "version")) {
                            current_entry.?.version = value;
